package com.menter.treatmentvault.ui.screens
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import com.menter.treatmentvault.*;import com.menter.treatmentvault.data.*;import kotlinx.coroutines.launch
@Composable fun SymptomScreen(back:()->Unit){val dao=(androidx.compose.ui.platform.LocalContext.current.applicationContext as TreatmentVaultApplication).database.dao();val list by dao.symptoms().collectAsState(emptyList());val scope=rememberCoroutineScope();var add by remember{mutableStateOf(false)};Page("症状记录",back){LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(8.dp)){items(list){v->Card{Column(Modifier.padding(12.dp)){Text(v.date,style=MaterialTheme.typography.titleMedium);Text("体温 ${v.temperature?:"-"}℃ · 体重 ${v.weight?:"-"}kg");Text(listOf(v.nausea,v.diarrhea,v.constipation,v.pain,v.fatigue).filter{it.isNotBlank()}.joinToString(" · "))}}};Button({add=true},Modifier.fillMaxWidth()){Text("记录今天症状")}}
if(add){var date by remember{mutableStateOf("")};var temp by remember{mutableStateOf("")};var notes by remember{mutableStateOf("")};AlertDialog({add=false},{TextButton({if(date.isNotBlank())scope.launch{dao.saveSymptom(SymptomEntity(date=date,temperature=temp.toDoubleOrNull(),notes=notes));add=false}}){Text("保存")}},dismissButton={TextButton({add=false}){Text("取消")}},title={Text("症状记录")},text={Column{Field(date,{date=it},"日期");Field(temp,{temp=it},"体温");Field(notes,{notes=it},"备注")}})} }
